import {
  IconOrangeRoleReviewer,
  IconBlueHeadPen,
  IconGreenRoleStamper,
  IconPinkCc,
  IconRedRoleCoordinator,
} from '../../../../assets/images';

export enum IRoleRecipent {
  // Người xem xét
  reviewer = 'reviewer',
  // Người ký
  signer = 'signer',
  // văn thư (người đóng dấu)
  stamper = 'stamper',
  //   cc
  cc = 'cc',
  //  Người điều phối
  coordinator = 'coordinator',
}

export enum ITypeParties {
  myOrganization = 'my-organization',
  organiztion = 'organization',
  individual = 'individual',
}

export const mapRoleRecipientToUi = (role: IRoleRecipent) => {
  switch (role) {
    case IRoleRecipent.reviewer:
      return {
        label: 'CD.singleCreate.reviewer',
        icon: <IconOrangeRoleReviewer width={14} height={14} />,
      };
    case IRoleRecipent.signer:
      return {
        label: 'CD.singleCreate.signer',
        icon: <IconBlueHeadPen width={14} height={14} />,
      };
    case IRoleRecipent.stamper:
      return {
        label: 'CD.singleCreate.stamper',
        icon: <IconGreenRoleStamper width={14} height={14} />,
      };
    case IRoleRecipent.cc:
      return {
        label: 'CD.singleCreate.cc',
        icon: <IconPinkCc width={14} height={14} />,
      };
    case IRoleRecipent.coordinator:
      return {
        label: 'CD.singleCreate.coordinator',
        icon: <IconRedRoleCoordinator width={14} height={14} />,
      };
    default:
      return {
        label: 'no role',
        icon: <IconRedRoleCoordinator width={14} height={14} />,
      };
      break;
  }
};

export const mapFullName = (role: IRoleRecipent) => {
  switch (role) {
    case IRoleRecipent.reviewer:
      return 'CD.singleCreate.reviewer';
    case IRoleRecipent.signer:
      return 'GS.autoConfig.nameSigner';
    case IRoleRecipent.stamper:
      return 'GS.autoConfig.namePersonStamping';
    case IRoleRecipent.cc:
      return 'GS.autoConfig.namePersonReceivingCC';
    case IRoleRecipent.coordinator:
      return 'GS.autoConfig.nameCoordinator';
    default:
      return 'GS.autoConfig.reviewer';
      break;
  }
};

