import {isEmpty} from 'lodash';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import ModalConfirmUpdateValidity from '../ModalConfirmUpdateValidity';
import PicDateView from './components/PicDateView';
import styles from './styles';
import {IDocumentTemplate} from '../../../../../model/interface/envelope.interface';
import Toast from 'react-native-toast-message';
import {View} from 'react-native';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import { useDocumentServices } from '../../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  toggleModal: () => void;
  data: IDocumentTemplate;
  onUpdateSuccess: () => void;
};

const ModalUpdateValidity = ({
  isVisible,
  toggleModal,
  data,
  onUpdateSuccess,
}: Props) => {
  const {t} = useTranslation();

  const [fromDate, setFromDate] = useState(() => {
    const currentDate = new Date();
    return new Date(data.effDate).getTime() < currentDate.getTime()
      ? currentDate
      : new Date(data.effDate);
  });

  const [toDate, setToDate] = useState(() => {
    const expDate = new Date(data.expDate);
    const currentDate = new Date();
    return expDate.getTime() > currentDate.getTime() ? expDate : currentDate;
  });
  const [dataConfirm, setDataConfirm] = useState<
    IDocumentTemplate[] | undefined
  >();
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const DocumentServices = useDocumentServices()
  const toggleModalConfirm = () => {
    setShowModalConfirm(!showModalConfirm);
  };

  const onPressSave = async () => {
    try {
      const effDate = new Date(fromDate);
      effDate.setHours(0, 0, 0);
      const expDate = new Date(toDate);
      expDate.setHours(23, 59, 59);
      const body = {
        ...data,
        effDate: effDate,
        expDate: expDate,
      };
      const res = await DocumentServices.saveDocumentTemplate(body);
      if (res?.status === 202) {
        setDataConfirm(res?.data as IDocumentTemplate[]);
        toggleModalConfirm();
        return;
      }
      toggleModal();
      toastSuccess();
      setTimeout(() => {
        onUpdateSuccess();
      }, 1000);
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    }
  };
  const toastSuccess = () => {
    Toast.show({
      type: 'success',
      text1: t('DC.DocumentTemplate.TxtUpdateSuccess'),
    });
  };

  const Content = () => {
    return (
      <View style={styles.content}>
        <PicDateView
          title={t('DC.DocumentTemplate.TxtEffectFrom')}
          label={t('DC.modal.TxtPicDate')}
          date={fromDate}
          maxDate={toDate}
          onChangeDate={setFromDate}
        />
        <PicDateView
          title={t('DC.DocumentTemplate.TxtEffectTo')}
          label={t('DC.modal.TxtPicDate')}
          date={toDate}
          minDate={fromDate}
          onChangeDate={setToDate}
        />
        <View style={styles.footer}>
          <ButtonCM label={t('CM.BtnConfirm')} onPress={onPressSave} />
        </View>
        {!isEmpty(dataConfirm) && (
          <ModalConfirmUpdateValidity
            isVisible={showModalConfirm}
            toggleModal={toggleModalConfirm}
            data={dataConfirm}
            onUpdateSuccess={() => {
              toastSuccess();
              toggleModal();
              onUpdateSuccess();
            }}
          />
        )}
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('DC.DocumentTemplate.TxtValidityDate')}
        renderContent={<Content />}
        onClose={toggleModal}
        isVisible={isVisible}
      />
    </>
  );
};

export default ModalUpdateValidity;
