import {Alert, TouchableOpacity, View} from 'react-native';
import React from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {
  formatText,
  getTaskPriorityLabel,
  getTitleProcessing,
  listStatus,
  mapStatus,
} from './helper';
import {useNavigation} from '@react-navigation/native';
import {isEmpty} from 'lodash';
import {
  EnvelopeStatus,
  INotification,
  RoleNotification,
  SignType,
  StatusNotification,
} from '../../../../../model/interface/notification.interface';
import {DateUtils} from '../../../../../utils';
import TextCM from '../../../../../components/Text';
import {NavigationName} from '../../../../../constants';
import CheckboxCM from '../../../../../components/Checkbox';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';
import useStoreNoti from '../../../store/store';

type Props = {
  data: INotification;
  isSignDozen: boolean;
};

const NotificationItem = ({data, isSignDozen}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const {currentSignDozens, toggleItemSignDozen} = useStoreNoti();

  const NotificationServices = useCreateNotiServices();

  const LIST_ITEM = [
    {
      title: t('NT.TxtReceivedDate'),
      value: DateUtils.convertDateToDDMMYYYYhhmm(data.createdDate),
    },
    {
      title: t('NT.TxtSentFrom'),
      value: data.sendFrom,
    },
  ];

  const renderStatus = () => {
    const dataStatus = mapStatus(data);

    if (dataStatus === StatusNotification.processing) {
      return (
        <TouchableOpacity style={styles.btnProcess} onPress={handleGoToWevview}>
          <TextCM style={styles.txtProcess}>
            {t(getTitleProcessing(data.role))}
          </TextCM>
        </TouchableOpacity>
      );
    }

    if (dataStatus === StatusNotification.processing1) {
      return (
        <TouchableOpacity
          style={styles.btnProcess1}
          onPress={handleGoToWevview}>
          <TextCM style={{...styles.txtProcess}}>
            {formatText(
              `${t('CM.Processing')} ${t(getTitleProcessing(data.role))}`,
            )}
          </TextCM>
        </TouchableOpacity>
      );
    }

    const status = listStatus.find(item => item.type === dataStatus);
    return (
      <View>
        <TextCM
          style={[
            styles.txtStatus,
            {
              color: status?.color,
            },
          ]}>
          • {t(status?.title ?? '')}
        </TextCM>
      </View>
    );
  };

  const handleGetJwtToken = async (envelopeId: string, recipientId: string) => {
    try {
      await NotificationServices.getJwtTokenSignature({
        envelopeId: envelopeId,
        recipientId: recipientId,
        email: null,
        password: null,
      });
    } catch (error) {
      return null;
    }
  };

  const handleGoToWevview = async () => {
    try {
      const signTypes = JSON.parse(data?.recipients[0]?.signTypes);
      const envelopeId = data?.resourceId.substr(4);
      const recipientId = data?.recipients[0]?.id;
      await handleGetJwtToken(envelopeId, recipientId);
      if (data.role === RoleNotification.coordinator) {
        Alert.alert(
          'Thông báo',
          'Tính năng điều phối trên app đang phát triển',
        );
        return;
        // navigation.navigate(NavigationName.DetailCoordinationScreen, {
        //   envelopeId: envelopeId,
        //   recipientId: recipientId,
        //   notiId: data?.id,
        // });
      }
      if (signTypes?.includes(SignType.EKYC)) {
        navigation.navigate(NavigationName.SignRuleScreen, {
          envelopeId: envelopeId,
          recipientId: recipientId,
        });
      } else {
        navigation.navigate(NavigationName.SignatureWebview, {
          envelopeId: envelopeId,
          recipientId: recipientId,
        });
      }
    } catch (error) {}
  };

  const handleNotificationDetails = async () => {
    navigation.navigate(NavigationName.NotificationDetail, {
      notiId: data.id,
    });
  };

  const renderItem = ({title, value}: {title: string; value: string}) => {
    return (
      <View style={styles.viewItem} key={title}>
        <TextCM style={styles.txtTitle}>{title}</TextCM>
        <TextCM style={styles.txtValue}>{value}</TextCM>
      </View>
    );
  };

  const renderPriority = () => {
    if (!data.refId) return null;

    const priority = getTaskPriorityLabel(data.refId);

    return <View style={styles.ctnIcon}>{priority.icon}</View>;
  };

  const checkShowSignDozen = () => {
    let rs = false;
    if (
      data.inputSign &&
      (data.status.startsWith('need-') || data.status.startsWith('processing'))
    ) {
      const recipient = data.recipients[0];
      if (!isEmpty(recipient) && recipient.status === 'processing') {
        rs = true;
      }
    }
    return rs;
  };

  const renderCheckBoxSignDozen = () => {
    const checkIsChecked =
      currentSignDozens.findIndex(sign => sign.id === data.id) !== -1;

    if (!checkShowSignDozen() || !isSignDozen) return null;
    if (
      data.status.startsWith('processing') &&
      data.envelopeStatus === EnvelopeStatus.processing
    ) {
      return (
        <CheckboxCM
          checked={checkIsChecked}
          onChange={() => toggleItemSignDozen(data)}
        />
      );
    }
  };

  return (
    <TouchableOpacity
      style={styles.container}
      onPress={handleNotificationDetails}>
      <View style={styles.viewHeader}>
        {renderCheckBoxSignDozen()}
        {renderPriority()}
        <TextCM style={styles.txtName}>{data.resourceName}</TextCM>
        {renderStatus()}
      </View>
      <View style={styles.viewBody}>
        {LIST_ITEM.map(renderItem)}
        <View style={styles.viewItem}>
          <TextCM style={styles.txtTitle}>{t('NT.TxtDepartment')}</TextCM>
          <View style={styles.viewValue}>
            {data.recipients.map(item => {
              return (
                <TextCM key={item.partyName} style={styles.txtRecipients}>
                  {item.attrs?.primaryRecipient?.[0]?.name}
                </TextCM>
              );
            })}
          </View>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default NotificationItem;
