export enum IAuthenDocumentTab {
  completed = 'completed',
  rejected = 'rejected',
  processing = 'processing',
}

export const getEnvelopeCecaPath = (tab: IAuthenDocumentTab, owner: string) => {
  switch (tab) {
    case IAuthenDocumentTab.completed:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          envelopeCecaRegistrySearch: {
            owner,
            status: tab,
          },
        },
      };
    case IAuthenDocumentTab.rejected:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          envelopeCecaRegistrySearch: {
            owner,
            status: tab,
          },
        },
      };
    case IAuthenDocumentTab.processing:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          envelopeCecaRegistrySearch: {
            owner,
            status: tab,
          },
        },
      };
    default:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          envelopeCecaRegistrySearch: {
            owner,
            status: tab,
          },
        },
      };
  }
};

export const colorIndicator = (activeTab: IAuthenDocumentTab) => {
  switch (activeTab) {
    case IAuthenDocumentTab.completed:
      return '#219342';
    case IAuthenDocumentTab.rejected:
      return '#DA3E33';
    case IAuthenDocumentTab.processing:
      return '#0673C6';
    default:
      return '#0673C6';
  }
};
