import {StatusNotification} from '../../../../../model/interface/notification.interface';

export const getTerms = (status: StatusNotification) => {
  switch (status) {
    case StatusNotification.accepted:
      return {status, envelopeStatus: 'processing'};

    case StatusNotification.completed:
    case StatusNotification.voided:
    case StatusNotification.overdue:
    case StatusNotification.rejected:
      return {envelopeStatus: status};

    case StatusNotification.delegated:
    case StatusNotification.forwarded:
      return {status};

    case StatusNotification.signer:
    case StatusNotification.coordinator:
    case StatusNotification.reviewer:
    case StatusNotification.stamper:
      return {
        status: 'processing',
        envelopeStatus: 'processing',
        role: status,
      };

    default:
      return {};
  }
};

export type GroupData = {
  id: string | number;
  label: string;
};
