import {useNavigation, useRoute} from '@react-navigation/native';
import {isEmpty, isUndefined} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import ModalCancelDocument from './components/ModalCancelDocument';
import ModalCopyDocument from './components/ModalCopyDocument';
import ModalCreateBatchesDocument from './components/ModalCreateBatchesDocument';
import ModalDisableDocument from './components/ModalDisableDocument';
import ModalExdateDocument from './components/ModalExdateDocument';
import ModalHashtagAlias from './components/ModalHashtagAlias';
import ModalRelateDocument from './components/ModalRelateDocument';
import {
  ActionItem,
  ActionType,
  getListAction,
  getNumRelatedDocument,
  handleDownloadUrl,
  isShowRelatedDocument,
} from './helper';
import styles from './styles';
import ListGeneralInfoDocument from './components/ListGeneralInforDocument';
import {
  IDocument,
  IFieldsByHeader,
  IOrganization,
  IRecipient,
} from '../../../model/interface/envelope.interface';
import {useAppSelector} from '../../../hook/useRedux';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';
import {
  ItemType,
  MainItemType,
} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {DateUtils} from '../../../utils';
import {NavigationName, String} from '../../../constants';
import TextCM from '../../../components/Text';
import HeaderCM from '../../../components/Header/HeaderCM';
import {
  IconCreateDate,
  IconGreyHashtag,
  IconGreyRelatedDocument,
  IconParties,
  IconRedWarning,
  IconUserCreate,
} from '../../../assets/images';
import ModalConfirm from '../../../components/ModalConfirm';
import {SignType} from '../../../model/interface/notification.interface';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../hook/apiHook/useApi';
import useFileDownloader from '../../../hook/useFileDownloader';

export enum ActionDocument {
  history = 'history',
  share = 'share',
}
const DocumentDetail = () => {
  const route = useRoute<any>();
  const dataRoute: IDocument & IOrganization = route.params.data;
  const {type} = dataRoute;
  const [data, setData] = useState(dataRoute);
  const [dataGeneralInfor, setDataGeneralInfor] = useState<IFieldsByHeader[]>(
    [],
  );
  const account = useAppSelector(state => state.account.dataAccount);
  const {mainCurrentFocused, currentFocused, reloadDataFn} = useDocumentStore();

  const [numRelatedDocument, setNumRelatedDocument] = useState(0);
  const [dataEnvelope, setDataEnvelope] = useState<any>();

  const {t} = useTranslation();

  const {onDownloadStart} = useFileDownloader(
    `${data.id}.zip`,
    handleDownloadUrl(data.id),
  );

  const navigation = useNavigation<any>();

  const DocumentServices = useDocumentServices();

  const [isShowModalCancel, setIsShowModalCancel] = useState(false);
  const [dataActionDocument, setDataActionDocument] = useState<any>();
  const [dataEkyc, setDataEkyc] = useState<any>();
  const [showModal, setShowModal] = useState({
    modalCopyDocument: false,
    modalRelateDocument: false,
    modalDisableDocument: false,
    modalConfirmDelete: false,
    modalExDate: false,
    modalHashtag: false,
    modalCreateBatches: false,
  });

  const getListActionInprogress = (isHistory: boolean) => {
    if (isHistory) {
      return getListAction(ItemType.CustomActionInprogressDocument);
    } else {
      return getListAction(ItemType.CustomActionInprogressDocumentNoHistory);
    }
  };
  const getListActionCancel = (isHistory: boolean) => {
    if (isHistory) {
      return getListAction(ItemType.CustomActionCancelDocument);
    } else {
      return getListAction(ItemType.CustomActionDocumentNoAction);
    }
  };
  const getListActionDone = () => {
    if (
      dataActionDocument.includes(ActionDocument.history) &&
      dataActionDocument.includes(ActionDocument.share)
    ) {
      return getListAction(ItemType.CustomActionDoneDocument);
    } else if (dataActionDocument.includes(ActionDocument.share)) {
      return getListAction(ItemType.CustomActionDoneDocumentNoHistory);
    } else if (dataActionDocument.includes(ActionDocument.history)) {
      return getListAction(ItemType.CustomActionDoneDocumentNoShare);
    } else {
      return getListAction(ItemType.CustomActionDocumentNoAction);
    }
  };

  const listAction = React.useMemo(() => {
    return mainCurrentFocused === MainItemType.MainDocumentOrganization &&
      !isUndefined(dataActionDocument)
      ? currentFocused === ItemType.InprogressDocumentOrganization
        ? getListActionInprogress(
            dataActionDocument.includes(ActionDocument.history),
          )
        : currentFocused === ItemType.DoneDocumentOrganization
        ? getListActionDone()
        : currentFocused === ItemType.CancelDocumentOrganization ||
          currentFocused === ItemType.ExpiredDocumentOrganization ||
          currentFocused === ItemType.RejectDocumentOrganization
        ? getListActionCancel(
            dataActionDocument.includes(ActionDocument.history),
          )
        : getListAction(data.type)
      : getListAction(data.type);
  }, [mainCurrentFocused, dataActionDocument, currentFocused, data.type]);

  useEffect(() => {
    getDetailById();
    try {
      DocumentServices.getActionDocumentById(data.custId).then(data => {
        if (!isEmpty(data)) {
          if (account?.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN)) {
            setDataActionDocument(['history', 'share', 'dowload']);
            if (account?.authorities?.includes(String.ROLE.ROLE_CUST_VIEWER)) {
              setDataActionDocument(JSON.parse(data.detail).action);
            }
          }
        } else {
          if (account?.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN)) {
            setDataActionDocument(['history', 'share', 'dowload']);
          }
        }
      });
    } catch (error) {
      console.log(error);
    }
  }, []);

  const getDetailById = async () => {
    try {
      const res = await DocumentServices.getEnvelopeDetailById(data.id);
      const dataEnvelop = await DocumentServices.getEnvelopeDetailByIdV1(
        data.id,
      );
      setDataEnvelope(dataEnvelop?.[0]);
      const resFavorite = await DocumentServices.getEnvelopeFavourite([
        data.id,
      ]);
      const favorites = !isEmpty(resFavorite) ? resFavorite[0] : undefined;
      setData({
        ...res,
        type,
        favorites,
      } as IDocument & IOrganization);
      let newRes = {...res, type, favorites};
      if (account.email === dataEnvelop[0]?.requester?.contact?.email) {
        setDataEkyc(
          dataEnvelop?.[0].parties[0].recipients?.filter((recipi: any) =>
            recipi?.signTypes?.includes(SignType.EKYC),
          ),
        );
      } else {
        setDataEkyc(
          dataEnvelop[0].parties[0].recipients?.filter(
            (recipi: IRecipient) =>
              recipi?.contact?.email === account.email &&
              recipi?.signTypes?.includes(SignType.EKYC),
          ),
        );
      }
      let dataDisable = newRes.header.fields.filter(
        (item: any) =>
          item.id !== 'envSubmittedFrom' &&
          item.id !== 'envName' &&
          item.id !== 'envNo' &&
          item.type !== 'Base64',
      );

      setDataGeneralInfor(
        dataDisable.filter((item: any) => {
          if (
            (currentFocused === ItemType.Done && item.id === 'envDate') ||
            (currentFocused === ItemType.InprogressDocumentOrganization &&
              item.id === 'envDate') ||
            (currentFocused === ItemType.SignFlow && item.id === 'envDate') ||
            (currentFocused === ItemType.DoneDocumentOrganization &&
              item.id === 'envDate') ||
            isEmpty(item.value) ||
            isUndefined(item.value)
          ) {
            return null;
          } else {
            return item;
          }
        }),
      );
      const resV1 = await DocumentServices.getEnvelopeDetailByIdV1(data.id);
      setNumRelatedDocument(getNumRelatedDocument(resV1));
    } catch (error) {}
  };

  const deleteDocument = async () => {
    try {
      const res = await DocumentServices.deleteDocument(data.id);
      Toast.show({
        type: 'success',
        text1: t('DC.Messages.TxtDeleteSuccess', {
          name: data.name,
        }),
      });
      setTimeout(() => {
        reloadDataFn();
      }, 1000);
      navigation.goBack();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    }
  };

  const toggleModal = (modalName: string) => () => {
    switch (modalName) {
      case 'modalCopyDocument':
        setShowModal({
          ...showModal,
          modalCopyDocument: !showModal.modalCopyDocument,
        });
        break;
      case 'modalRelateDocument':
        setShowModal({
          ...showModal,
          modalRelateDocument: !showModal.modalRelateDocument,
        });
        break;
      case 'modalDisableDocument':
        setShowModal({
          ...showModal,
          modalDisableDocument: !showModal.modalDisableDocument,
        });
        break;
      case 'modalConfirmDelete':
        setShowModal({
          ...showModal,
          modalConfirmDelete: !showModal.modalConfirmDelete,
        });
        break;
      case 'modalExDate':
        setShowModal({
          ...showModal,
          modalExDate: !showModal.modalExDate,
        });
        break;
      case 'modalHashtag':
        setShowModal({
          ...showModal,
          modalHashtag: !showModal.modalHashtag,
        });
        break;
      case 'modalCreateBatches':
        setShowModal({
          ...showModal,
          modalCreateBatches: !showModal.modalCreateBatches,
        });
        break;
      default:
        break;
    }
  };

  const getNameDateCreate = () => {
    if (type === ItemType.CCDocument || type === ItemType.Favorite) {
      return t('DC.TxtCreateDate');
    }
    switch (data.status) {
      case ItemType.Done:
      case ItemType.SignFlow:
        return t('DC.TxtDoneDate');
      default:
        return t('DC.TxtCreateDate');
    }
  };

  const getDataDateCreate = () => {
    if (type === ItemType.Favorite) {
      return DateUtils.convertDateToDDMMYYYY(data.createdDate);
    }
    switch (data.status) {
      case ItemType.Done:
      case ItemType.SignFlow:
        return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate);
      default:
        return DateUtils.convertDateToDDMMYYYY(data.createdDate);
    }
  };

  const getNameDateSign = () => {
    switch (type) {
      case ItemType.InprogressDocumentOrganization:
      case ItemType.DoneDocumentOrganization:
        return t('DC.TxtSignDate');
      case ItemType.CancelDocumentOrganization:
        return t('DC.TxtCancelDate');
      case ItemType.RejectDocumentOrganization:
        return t('DC.TxtRejectDate');
      case ItemType.ExpiredDocumentOrganization:
        return t('DC.TxtExpiredDate');
      default:
        return t('DC.TxtExpirationDate');
    }
  };
  const getDataDateSign = () => {
    switch (type) {
      case ItemType.InprogressDocumentOrganization:
      case ItemType.DoneDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.signDate) || '---';
      case ItemType.CancelDocumentOrganization:
      case ItemType.RejectDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.lastModifiedDate) || '---';
      case ItemType.ExpiredDocumentOrganization:
        return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate) || '---';
      default:
        return DateUtils.convertDateToDDMMYYYY(
          DateUtils.addDays(data.createdDate, data.dueInDays),
        );
    }
  };

  const getTitleExpirationDate = () => {
    if (type === ItemType.CCDocument || type === ItemType.Favorite) {
      return t('DC.TxtExpirationDate');
    }

    switch (data.status) {
      case ItemType.Done:
        return t('DC.TxtSignDate');
      case ItemType.Cancel:
        return t('DC.TxtCancelDate');
      case ItemType.Reject:
        return t('DC.TxtRejectDate');
      case ItemType.Expired:
      case ItemType.Trash:
        return t('DC.TxtExpiredDate');
      default:
        return t('DC.TxtExpirationDate');
    }
  };

  const getDataExpirationDate = () => {
    if (type === ItemType.CCDocument || type === ItemType.Favorite) {
      return DateUtils.convertDateToDDMMYYYY(
        DateUtils.addDays(data.createdDate, data.dueInDays),
      );
    }
    switch (data.status) {
      case ItemType.Done:
      case ItemType.SignFlow:
        return DateUtils.convertDateToDDMMYYYY(data.signDate) || '---';
      case ItemType.Cancel:
      case ItemType.Reject:
      case ItemType.Trash:
        return DateUtils.convertDateToDDMMYYYY(data.lastModifiedDate) || '---';
      case ItemType.Expired:
        return DateUtils.convertDateToDDMMYYYY(data.flowFinishDate) || '---';
      default:
        return DateUtils.convertDateToDDMMYYYY(
          DateUtils.addDays(data.createdDate, data.dueInDays),
        );
    }
  };

  const handleGetUrlContract = async () => {
    try {
      navigation.navigate(NavigationName.ViewPdfDocument, {
        envelopeId: dataEnvelope?.id,
        docId: dataEnvelope?.documents?.[0]?.id,
      });
    } catch (error) {}
  };

  const onNavigation = (type: string) => () => {
    switch (type) {
      case ActionType.open:
        handleGetUrlContract();
        break;
      case ActionType.history:
        navigation.navigate(NavigationName.DocumentHistory, {
          data,
        });
        break;
      case ActionType.cancel:
        toggleModalCancel();
        break;
      case ActionType.copy:
        toggleModal('modalCopyDocument')();
        break;
      case ActionType.disable:
        toggleModal('modalDisableDocument')();
        break;
      case ActionType.related:
        toggleModal('modalRelateDocument')();
        break;
      case ActionType.download:
        onDownloadStart();
        break;
      case ActionType.share:
        navigation.navigate(NavigationName.DocumentShareScreen, {data});
        break;
      case ActionType.delete:
        toggleModal('modalConfirmDelete')();
        break;
      case ActionType.exDate:
        toggleModal('modalExDate')();
        break;
      case ActionType.hastagAlias:
        toggleModal('modalHashtag')();
        break;
      case ActionType.createBatches:
        toggleModal('modalCreateBatches')();
        break;
      case ActionType.addRelateDocument:
        navigation.navigate(NavigationName.DocumentRelateScreen, {data});
      default:
        break;
    }
  };

  const renderItemAction = (value: ActionItem) => {
    if (value.type === ActionType.disable && data.disableDocument) return null;

    if (value.type === ActionType.exDate && !checkShowWarning()) return null;

    return (
      <TouchableOpacity
        style={[styles.btnAction]}
        key={value.type}
        onPress={onNavigation(value.type)}>
        <View style={styles.viewIcon}>{value.icon}</View>
        <TextCM style={styles.txtNameAction}>{value.name}</TextCM>
      </TouchableOpacity>
    );
  };

  const toggleModalCancel = () => {
    setIsShowModalCancel(!isShowModalCancel);
  };

  const onCancelSuccess = () => {
    reloadDataFn();
    navigation.goBack();
  };

  const renderWarning = () => {
    if (type === ItemType.Inprogress && checkShowWarning()) {
      return (
        <View style={styles.viewWarning}>
          <IconRedWarning width={16} height={16} />
          <TextCM style={styles.txtWarning}>
            {t('DC.TxtDesExDateDocument')}
          </TextCM>
        </View>
      );
    }
    return null;
  };

  const renderAlias = () => {
    if (type === ItemType.Favorite && data.favorites?.aliasName) {
      return (
        <TextCM style={styles.txtAlias}>({data.favorites?.aliasName})</TextCM>
      );
    }
    return null;
  };

  const checkShowWarning = () => {
    const currentDate = new Date();
    const startDate = DateUtils.addDays(data.createdDate, data.dueInDays - 2);
    const endDate = DateUtils.addDays(data.createdDate, data.dueInDays + 4);
    return (
      currentDate.getTime() >= startDate.getTime() &&
      currentDate.getTime() <= endDate.getTime()
    );
  };

  const getDataHashtag = () => {
    return data.favorites?.hashTag?.map(hashtag => `#${hashtag}`).join(', ');
  };

  const onExdateSuccess = () => {
    setTimeout(() => {
      getDetailById();
      reloadDataFn();
    }, 1000);
  };

  const onUpdateSuccess = () => {
    getDetailById();
    reloadDataFn();
  };

  const checkEkyc = dataEkyc?.some((item: any) => {
    if (
      item.contact.name === account.lastName &&
      item.contact.email === account.email
    ) {
      return true;
    }
    return false;
  });

  return (
    <SafeAreaView
      edges={['bottom']}
      style={[
        styles.ctnMain,
        {backgroundColor: dataGeneralInfor?.length > 0 ? '#FFF' : '#F1F1F1'},
      ]}>
      <HeaderCM title={t('DC.TxtDetailDocument')} />
      <ScrollView style={{flex: 1, backgroundColor: '#fff'}}>
        <>
          <View style={styles.contain}>
            <View style={styles.body}>
              <TextCM
                style={[
                  styles.txtTitle,
                  data.disableDocument &&
                    mainCurrentFocused === MainItemType.MainDocument &&
                    styles.txtRed,
                ]}>
                {data.name}
              </TextCM>
              {renderWarning()}
              {renderAlias()}
              <TextCM style={styles.txtCode}>{data.envNo || '---'}</TextCM>
              <View style={styles.viewList}>
                {mainCurrentFocused ===
                  MainItemType.MainDocumentOrganization && (
                  <View style={styles.viewItem}>
                    <View style={styles.viewName}>
                      <IconUserCreate width={14} height={17} />
                      <TextCM style={styles.txtName}>
                        {t('DC.TxtUserCreate')}
                      </TextCM>
                    </View>
                    <TextCM style={styles.txtValue}>{data.createdBy}</TextCM>
                  </View>
                )}
                {type === ItemType.Favorite &&
                  !isEmpty(data.favorites?.hashTag) && (
                    <View style={styles.viewItem}>
                      <View style={styles.viewName}>
                        <IconGreyHashtag width={16} height={16} />
                        <TextCM style={styles.txtName}>
                          {t('DC.TxtHashtag')}
                        </TextCM>
                      </View>
                      <TextCM style={styles.txtValueHashtag}>
                        {getDataHashtag()}
                      </TextCM>
                    </View>
                  )}
                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <IconCreateDate width={18} height={17} />
                    <TextCM style={styles.txtName}>
                      {getNameDateCreate()}
                    </TextCM>
                  </View>
                  <TextCM style={styles.txtValue}>{getDataDateCreate()}</TextCM>
                </View>
                {isShowRelatedDocument(type) && (
                  <View style={styles.viewItem}>
                    <View style={styles.viewName}>
                      <IconGreyRelatedDocument width={16} height={16} />
                      <TextCM style={styles.txtName}>
                        {t('DC.TxtSuggestionDocument')}
                      </TextCM>
                    </View>
                    <TextCM style={styles.txtValue}>
                      {numRelatedDocument}
                    </TextCM>
                  </View>
                )}
                {mainCurrentFocused ===
                  MainItemType.MainDocumentOrganization && (
                  <View style={styles.viewItem}>
                    <View style={styles.viewName}>
                      <IconCreateDate width={18} height={17} />
                      <TextCM style={styles.txtName}>
                        {getNameDateSign()}
                      </TextCM>
                    </View>
                    <TextCM style={styles.txtValue}>{getDataDateSign()}</TextCM>
                  </View>
                )}
                {data.status !== ItemType.Draft &&
                  mainCurrentFocused !==
                    MainItemType.MainDocumentOrganization && (
                    <View style={styles.viewItem}>
                      <View style={styles.viewName}>
                        <IconCreateDate width={18} height={17} />
                        <TextCM style={styles.txtName}>
                          {getTitleExpirationDate()}
                        </TextCM>
                      </View>
                      <TextCM style={styles.txtValue}>
                        {getDataExpirationDate()}
                      </TextCM>
                    </View>
                  )}

                <View style={styles.viewItem}>
                  <View style={styles.viewName}>
                    <IconParties width={20} height={17} />
                    <TextCM style={styles.txtName}>{t('DC.TxtParties')}</TextCM>
                  </View>
                  <View style={styles.viewValueParties}>
                    {!isEmpty(data?.parties) ? (
                      data?.parties?.map((item: any) => {
                        if (item.type === 'cc') return null;
                        return (
                          <TextCM style={styles.txtValue} key={item.id}>
                            {item.type !== 'individual'
                              ? item.name || '---'
                              : item.recipients?.[0]?.contact?.name}
                          </TextCM>
                        );
                      })
                    ) : (
                      <TextCM style={styles.txtValue}>---</TextCM>
                    )}
                  </View>
                </View>
              </View>
            </View>
            <View style={styles.action}>
              {listAction?.map(item => renderItemAction(item))}
            </View>
          </View>
          {(dataGeneralInfor?.length > 0 ||
            (dataEkyc?.length === 1 && !checkEkyc) ||
            dataEkyc?.length > 1) && (
            <>
              <ListGeneralInfoDocument
                data={dataGeneralInfor}
                dataEkyc={dataEkyc}
              />
            </>
          )}
        </>
      </ScrollView>

      {isShowModalCancel && (
        <ModalCancelDocument
          isVisible={isShowModalCancel}
          onClose={toggleModalCancel}
          data={data}
          onCancelSuccess={onCancelSuccess}
        />
      )}
      {showModal.modalCopyDocument && (
        <ModalCopyDocument
          onClose={toggleModal('modalCopyDocument')}
          isVisible={showModal.modalCopyDocument}
          data={data}
        />
      )}
      {showModal.modalRelateDocument && (
        <ModalRelateDocument
          onClose={toggleModal('modalRelateDocument')}
          isVisible={showModal.modalRelateDocument}
          envelopeId={data.id}
        />
      )}
      {showModal.modalCreateBatches && (
        <ModalCreateBatchesDocument
          onClose={toggleModal('modalCreateBatches')}
          isVisible={showModal.modalCreateBatches}
          data={data}
        />
      )}

      {showModal.modalDisableDocument && (
        <ModalDisableDocument
          onClose={toggleModal('modalDisableDocument')}
          isVisible={showModal.modalDisableDocument}
          data={data}
          fetching={getDetailById}
        />
      )}
      {showModal.modalConfirmDelete && (
        <ModalConfirm
          onConfirm={deleteDocument}
          onClose={toggleModal('modalConfirmDelete')}
          isVisible={showModal.modalConfirmDelete}
          title={t('DC.confirmDeleteDocument')}
        />
      )}
      {showModal.modalExDate && (
        <ModalExdateDocument
          data={data}
          toggleModal={toggleModal('modalExDate')}
          isVisible={showModal.modalExDate}
          onExdateSuccess={onExdateSuccess}
        />
      )}
      {showModal.modalHashtag && (
        <ModalHashtagAlias
          data={data}
          toggleModal={toggleModal('modalHashtag')}
          isVisible={showModal.modalHashtag}
          onSuccess={onUpdateSuccess}
        />
      )}
    </SafeAreaView>
  );
};

export default DocumentDetail;
