import {yupResolver} from '@hookform/resolvers/yup';
import React, {useEffect, useState} from 'react';
import {FormProvider, useForm} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import ModalCreateTemplate from '../ModalCreateTemplate';
import ModalPicReasonTemplate from '../ModalPicReasonTemplate';
import YupTextField from './components/YupTextField';
import styles from './styles';
import {
  IDocument,
  IReasonTemplate,
} from '../../../../../model/interface/envelope.interface';
import {
  IcBlackLeftArrow,
  IcBluePlus,
  IcCheckbox,
  IcCheckboxSelect,
  IconGreyDownArrow,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalCancelDocument = {
  onClose: () => void;
  isVisible: boolean;
  data: IDocument;
  onCancelSuccess: () => void;
};

const ModalCancelDocument = ({
  onClose,
  isVisible,
  data,
  onCancelSuccess,
}: ModalCancelDocument) => {
  const {t} = useTranslation();
  const schema = yup.object().shape({
    reason: yup.string().required(t('SU.fieldRequired')),
  });
  const insets = useSafeAreaInsets();
  const [showModalPicReason, setShowModalPicReason] = useState(false);
  const [showModalCreateTemplate, setShowModalCreateTemplate] = useState(false);
  const [disableDocument, setDisableDocument] = useState(data.disableDocument);
  const DocumentServices = useDocumentServices();
  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      reason: '',
    },
  });

  const toggleModalPicReason = () => {
    setShowModalPicReason(!showModalPicReason);
  };

  const toggleModalCreateTemplate = () => {
    setShowModalCreateTemplate(!showModalCreateTemplate);
  };

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.cancelDocument(data.id, {
        reason: methods.getValues('reason'),
      });
      Toast.show({
        type: 'success',
        text1: t('DC.Messages.TxtCancelDocumentSuccess', {
          name: data.name,
        }),
      });
      onCancelSuccess();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      onClose();
    }
  };

  const onPressDisableDocument = () => {
    setDisableDocument(!disableDocument);
  };

  const onPicTemplate = (value: IReasonTemplate) => {
    methods.setValue('reason', value.content?.slice(0, 100));
    methods.trigger();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>
                {t('DC.CancelDocument.TxtTitle')}
              </TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <TextCM style={styles.txtDes}>
                {t('DC.CancelDocument.TxtDes')}
              </TextCM>
              <View style={styles.viewAction}>
                <TouchableOpacity
                  style={styles.viewDisable}
                  onPress={onPressDisableDocument}>
                  <View>
                    {disableDocument ? (
                      <IcCheckboxSelect width={20} height={20} />
                    ) : (
                      <IcCheckbox width={20} height={20} />
                    )}
                  </View>
                  <TextCM style={styles.txtDisable}>
                    {t('DC.CancelDocument.TxtDisable')}
                  </TextCM>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.viewCreate}
                  onPress={toggleModalCreateTemplate}>
                  <IcBluePlus width={16} height={16} />
                  <TextCM style={styles.txtCreate}>
                    {t('DC.CancelDocument.TxtCreateTemplateMessage')}
                  </TextCM>
                </TouchableOpacity>
              </View>
              <FormProvider {...methods}>
                <YupTextField
                  controlName={'reason'}
                  label={t('DC.CancelDocument.TxtReasonYou')}
                  viewIconRight={<IconGreyDownArrow width={18} height={18} />}
                  multiline
                  onPressIconRight={toggleModalPicReason}
                  maxLength={100}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('DC.CancelDocument.BtnCancelDocument')}
                  onPress={onSubmit}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
      <ModalCreateTemplate
        isVisible={showModalCreateTemplate}
        onClose={toggleModalCreateTemplate}
        data={data}
      />
      <ModalPicReasonTemplate
        isVisible={showModalPicReason}
        onClose={toggleModalPicReason}
        onPicTemplate={onPicTemplate}
      />
    </Modal>
  );
};

export default ModalCancelDocument;
